/* Strict actual caller transport, full profile and named-save replay. */
#include "gc/gacha.h"
#include "pr/battle.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
#include <errno.h>
static FILE *fp;static char line[8192];static int lineno;static gc_system sys,expected,loaded,before;static unsigned char savebuf[524288];
static void bad(const char *s){fprintf(stderr,"invalid egg trace line%d: %s\n",lineno,s);exit(2);}
static char *record(char c){if(!fgets(line,sizeof line,fp))bad("EOF");lineno++;if(line[0]!=c||line[1]!=' '||!strchr(line,'\n'))bad("record/order/length");return line+2;}
static long token(char **s,long lo,long hi){char *end;errno=0;long value=strtol(*s,&end,10);if(end==*s||errno==ERANGE||value<lo||value>hi)bad("integer token range");*s=end;return value;}
static void vec(char tag,double *v,int n){char *s=record(tag),*end;for(int i=0;i<n;i++){v[i]=strtod(s,&end);if(s==end||!isfinite(v[i]))bad("finite fields");s=end;}while(isspace((unsigned char)*s))s++;if(*s)bad("extra fields");}
static int integer(double v,int lo,int hi){if(v<lo||v>hi||v!=floor(v))bad("integer range");return v;}
static void rng(char tag,pr_rng *r){double v[4];vec(tag,v,4);if(v[0]!=floor(v[0])||v[0]<0||v[0]>2091639)bad("RNG carry");for(int i=1;i<4;i++)if(v[i]<0||v[i]>=1)bad("RNG fraction");*r=(pr_rng){v[0],v[1],v[2],v[3],0};}
static bool rng_eq(const pr_rng *a,const pr_rng *b){return a->c==b->c&&a->s0==b->s0&&a->s1==b->s1&&a->s2==b->s2;}
static void profile(char tag,gc_system *s){double v[17];vec(tag,v,17);for(int i=0;i<17;i++)if(v[i]<0||v[i]>UINT32_MAX||v[i]!=floor(v[i]))bad("profile number");for(int i=0;i<4;i++){s->voucher_counts[i]=v[i];s->egg_pity[i]=v[4+i];s->unlock_pity[i]=integer(v[8+i],0,10);}s->stats.eggs_pulled=v[12];s->stats.rare_eggs_pulled=v[13];s->stats.epic_eggs_pulled=v[14];s->stats.legendary_eggs_pulled=v[15];s->stats.manaphy_eggs_pulled=v[16];}
static void egg(char tag,gc_egg *e){double v[10];vec(tag,v,10);memset(e,0,sizeof *e);if(v[0]<0||v[0]>UINT32_MAX||v[0]!=floor(v[0]))bad("egg id");e->id=v[0];e->hatch_waves=integer(v[1],0,100);e->tier=integer(v[2],0,3);e->species=integer(v[3],1,GC_MAX_SPECIES_ID);e->source_type=integer(v[4],0,2);e->variant_tier=integer(v[5],0,2);e->is_shiny=integer(v[6],0,1);e->egg_move_index=integer(v[7],0,3);e->override_hidden_ability=integer(v[8],0,1);if(v[9]<0||v[9]>8640000000000000.0||v[9]!=floor(v[9]))bad("timestamp");e->timestamp_ms=v[9];}
int main(int argc,char **argv){if(argc!=2||!(fp=fopen(argv[1],"r")))return 2;if(!fgets(line,sizeof line,fp)||strncmp(line,"GACHA ",6))return 2;lineno=1;char *header=line+6;token(&header,1,1);int n=token(&header,120,100000),pool=token(&header,gc_egg_pool_count,gc_egg_pool_count);if(strcmp(header,"\n"))bad("header end");
 for(int i=0;i<pool;i++){double v[4];vec('M',v,4);const gc_egg_pool_entry *p=&gc_egg_pool[i];if(v[0]!=p->species||v[1]!=p->cost||v[2]!=p->tier||v[3]!=p->variants)bad("pinned pool manifest");}
 int failures=0,success=0,capacity=0,cost=0,eggs=0,shiny=0,variants=0,manaphy=0,legendary=0,featured=0,machines[3]={0},options[5]={0},saves=0,guarantees=0;
 for(int ci=0;ci<n;ci++){
  double c[7];vec('C',c,7);if(c[0]!=ci)bad("case order");gc_gacha_ctx ctx={0};ctx.machine=integer(c[1],0,2);ctx.cursor=integer(c[2],0,4);if(c[3]<0||c[3]>8640000000000000.0||c[3]!=floor(c[3]))bad("clock");ctx.timestamp_ms=c[3];int result=integer(c[4],0,2),nb=integer(c[5],0,99),focus=integer(c[6],1,GC_MAX_SPECIES_ID);rng('R',&ctx.scene_rng);rng('E',&ctx.entropy);gc_system_init_defaults(&sys);profile('V',&sys);
  char *caught=record('K');if(strlen(caught)!=(size_t)pool+1)bad("caught bitmap count");for(int i=0;i<pool;i++){if(caught[i]!='0'&&caught[i]!='1')bad("caught bitmap");sys.dex[gc_egg_pool[i].species].caught_attr=caught[i]-'0';}
  double count;vec('B',&count,1);if(count!=nb)bad("stock count");sys.n_eggs=nb;for(int i=0;i<nb;i++)egg('I',&sys.eggs[i]);before=sys;expected=sys;gc_gacha_ctx original=ctx;
  vec('A',&count,1);expected.n_eggs=integer(count,0,99);for(int i=0;i<expected.n_eggs;i++)egg('O',&expected.eggs[i]);profile('W',&expected);pr_rng after_scene,after_entropy;rng('S',&after_scene);rng('T',&after_entropy);double draws;vec('U',&draws,1);int nd=integer(draws,0,650);
  char *d=record('D');long display=token(&d,0,25);int order[25];bool seen[25]={0};for(int i=0;i<display;i++){long value=token(&d,0,display-1);if(seen[value])bad("display permutation");seen[value]=true;order[i]=value;}while(isspace((unsigned char)*d))d++;if(*d)bad("display fields");double last;vec('X',&last,1);if(last!=ci)bad("case end");
  gc_gacha_result output={.n=-9};gc_gacha_result unchanged=output;const char *why;bool accepted=gc_system_gacha_pull(&sys,&ctx,&output,&why);bool same=accepted==(result==0)&&!memcmp(&sys,&expected,sizeof sys)&&rng_eq(&ctx.scene_rng,&after_scene)&&rng_eq(&ctx.entropy,&after_entropy)&&ctx.entropy_draws==(unsigned)nd&&gc_gacha_featured_species(original.timestamp_ms)==focus;
  if(accepted){if(output.n!=display)same=false;for(int i=0;i<display;i++)if(output.order[i]!=order[i])same=false;success++;machines[original.machine]++;options[original.cursor]++;if(nd<26*display)guarantees++;for(int i=nb;i<sys.n_eggs;i++){gc_egg *e=&sys.eggs[i];eggs++;shiny+=e->is_shiny;variants+=e->variant_tier>0;bool special=e->species==SPECIES_ID_MANAPHY||e->species==SPECIES_ID_PHIONE;manaphy+=special;legendary+=e->tier==3;featured+=original.machine==1&&e->tier==3&&e->species==focus;}}
  else{if(memcmp(&sys,&before,sizeof sys)||memcmp(&ctx,&original,sizeof ctx)||memcmp(&output,&unchanged,sizeof output))same=false;if(result==1){capacity++;if(!why||strcmp(why,"egg:tooManyEggs"))same=false;}else{cost++;if(!why||strcmp(why,"egg:notEnoughVouchers"))same=false;}}
  size_t bytes=gc_system_save(&sys,savebuf,sizeof savebuf);if(!bytes||!gc_system_load(&loaded,savebuf,bytes,&why)||memcmp(&loaded,&sys,sizeof sys))same=false;else saves++;
  if(!same){if(failures<8){fprintf(stderr,"FAIL egg%d machine%d option%d result%d/%d stock%d/%d draws%u/%d profile%d scene%d entropy%d focus%d/%d (%s)\n",ci,original.machine,original.cursor,accepted,result,sys.n_eggs,expected.n_eggs,ctx.entropy_draws,nd,!memcmp(&sys,&expected,sizeof sys),rng_eq(&ctx.scene_rng,&after_scene),rng_eq(&ctx.entropy,&after_entropy),gc_gacha_featured_species(original.timestamp_ms),focus,why?why:"");for(int i=nb;i<sys.n_eggs&&i<expected.n_eggs;i++)if(memcmp(&sys.eggs[i],&expected.eggs[i],sizeof(gc_egg))){gc_egg *a=&sys.eggs[i],*b=&expected.eggs[i];fprintf(stderr,"egg%d id%u/%u tier%d/%d species%d/%d shiny%d/%d variant%d/%d move%d/%d waves%d/%d\n",i,a->id,b->id,a->tier,b->tier,a->species,b->species,a->is_shiny,b->is_shiny,a->variant_tier,b->variant_tier,a->egg_move_index,b->egg_move_index,a->hatch_waves,b->hatch_waves);break;}}failures++;}
 }
 double footer[18];vec('Z',footer,18);int counts[18]={n,success,capacity,cost,eggs,shiny,variants,manaphy,legendary,featured,machines[0],machines[1],machines[2],options[0],options[1],options[2],options[3],options[4]};for(int i=0;i<18;i++)if(footer[i]!=counts[i])bad("footer coverage");if(fgetc(fp)!=EOF)bad("trailing data");fclose(fp);
 printf("Egg gacha actual: cases%d exact%d failed%d success%d capacity%d cost%d eggs%d shiny%d variants%d manaphy%d legendary%d featured%d guaranteed_last%d saves%d\n",n,n-failures,failures,success,capacity,cost,eggs,shiny,variants,manaphy,legendary,featured,guarantees,saves);if(!success||!capacity||!cost||(n>=2000&&(!shiny||!variants||!manaphy||!legendary||!featured||!guarantees))||saves!=n)bad("meaningful coverage");for(int i=0;i<3;i++)if(!machines[i])bad("machine coverage");for(int i=0;i<5;i++)if(!options[i])bad("option coverage");return failures?1:0;
}
